<?php $starters=pay_template_starters();$attributes=$v['attributes']??[];?>
<section class="pay-template-editor" data-pay-template-editor>
 <h3>Payslip design</h3><p class="pay-muted">Use the standard payslip or paste your own HTML. A run keeps the design saved when that run was created. Existing payslips stay unchanged.</p>
 <?php pay_select('template_mode','Layout',$v['template_mode']??'standard',['standard'=>'Standard payslip','html'=>'Custom HTML']);?>
 <div class="pay-actions" style="margin:16px 0"><?php foreach($starters as $name=>$html):?><button type="button" class="button" data-template-starter="<?=h($html)?>"><?=h($name)?> layout</button><?php endforeach;?></div>
 <label>HTML template<textarea name="html_template" rows="15" maxlength="100000" spellcheck="false" style="font-family:monospace;width:100%;box-sizing:border-box"><?=h($v['html_template']??'')?></textarea></label>
 <p class="pay-muted">Paste the HTML body only. Use tables and inline styles. Scripts, external resources, style blocks and forms are not supported. Put attributes in text, for example &lt;h2&gt;[employee_name]&lt;/h2&gt;. Use [company_logo] for your saved company logo.</p>
 <details><summary>Available attributes — click to insert</summary><div class="pay-actions" style="flex-wrap:wrap;margin:12px 0"><?php foreach(pay_template_fields() as $field):?><button type="button" class="button" data-template-token="<?=h($field)?>">[<?=h($field)?>]</button><?php endforeach;?></div></details>
 <h4>Custom attributes</h4><p class="pay-muted">Create a name such as <code>office_label</code> and use <code>[office_label]</code> in HTML. Source: fixed text, an existing field name, or an exact salary component code such as BASIC. Missing component codes display zero; hidden salary components stay aggregated.</p>
 <div data-attribute-rows><?php foreach($attributes as $i=>$attr):?><div class="pay-grid" data-attribute-row><?php pay_text('attributes['.$i.'][name]','Attribute name',['attributes['.$i.'][name]'=>$attr['name']]);pay_select('attributes['.$i.'][source]','Source',$attr['source'],['text'=>'Fixed text','field'=>'Saved field','component'=>'Salary component code']);pay_text('attributes['.$i.'][value]','Text / field name / code',['attributes['.$i.'][value]'=>$attr['value']]);?><button type="button" class="button" data-remove-attribute>Remove</button></div><?php endforeach;?></div>
 <div class="pay-actions" style="margin:16px 0"><button type="button" class="button" data-add-attribute>Add attribute</button><button type="button" class="button primary" data-preview-template>Preview sample payslip</button></div>
 <p role="status" data-template-message></p><iframe title="Sample payslip preview — not employee data" sandbox hidden style="width:100%;height:700px;border:1px solid #ddd;border-radius:12px;background:white" data-template-preview></iframe>
